    "id": "hunter-conclave",
    "name": "Conclave do Caçador",
    "className": "Patrulheiro",
    "sourceHeading": "CONCLAVE DO CAÇADOR",
    "sourceHeadingAsPrinted": "CONCLAVE DO CAÇADOR",
    "chapter": "Capítulo 3 — Classes",
